INSERT INTO collection_pages VALUES('0e2743e2465cfc2a75c5ae39e96f9ee701e4bfa51df11fc1ed234c15afcbd48e','5d7fd1361b099e009edf9dfe101bfcddc100692ef6b3a52c1ee79166aeddbb43','{"hasNext":false,"items":[{"author":{"account":{"login":"vyogo-dev","providerType":"User"},"email":"dev@vyogo.tech","name":"vyogodev"},"authoredDate":"2026-09-10T06:59:14Z","committedDate":"2026-09-10T06:59:14Z","committer":{"account":{"login":"vyogo-dev","providerType":"User"},"email":"dev@vyogo.tech","name":"vyogodev"},"observedAt":"2026-10-09T00:36:12.391Z","repositoryId":1363643748,"sha":"b5851303ae486a774e5818165bf67dac8c50a512"}],"observedAt":"2026-10-09T00:36:12.391Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/333592221?v=4","events_url":"https://api.github.com/users/vyogo-dev/events{/privacy}","followers_url":"https://api.github.com/users/vyogo-dev/followers","following_url":"https://api.github.com/users/vyogo-dev/following{/other_user}","gists_url":"https://api.github.com/users/vyogo-dev/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/vyogo-dev","id":333592221,"login":"vyogo-dev","node_id":"U_kgDOE-I2nQ","organizations_url":"https://api.github.com/users/vyogo-dev/orgs","received_events_url":"https://api.github.com/users/vyogo-dev/received_events","repos_url":"https://api.github.com/users/vyogo-dev/repos","site_admin":false,"starred_url":"https://api.github.com/users/vyogo-dev/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/vyogo-dev/subscriptions","type":"User","url":"https://api.github.com/users/vyogo-dev","user_view_type":"public"},"comments_url":"https://api.github.com/repos/vyogotech/frappe-operator-console-plugin/commits/b5851303ae486a774e5818165bf67dac8c50a512/comments","commit":{"author":{"date":"2026-09-10T06:59:14Z","email":"dev@vyogo.tech","name":"vyogodev"},"comment_count":0,"committer":{"date":"2026-09-10T06:59:14Z","email":"dev@vyogo.tech","name":"vyogodev"},"message":"feat: OpenShift Console dynamic plugin for the Frappe Operator\n\nRenders the operator''s CRDs as Frappe concepts rather than raw YAML. A bench\nis a fleet with a database and Redis behind it; a site is a tenant with\nmigrations, app installs, backups and restores in its history. The plugin\nregisters its own navigation section, so none of it is reached through\nCustom Resource Definitions.\n\n- List pages and detail tabs for FrappeBench and FrappeSite, including Data\n  Services, Resource Metrics via the console''s Prometheus browser, and an\n  Operations tab that gathers a tenant''s SiteMigration, SiteApp, SiteBackup\n  and SiteRestore CRs into one place\n- Actions for migrate, install app, back up, restore, create site and re-run\n  initialization; each creates the corresponding CR and carries an\n  accessReview so the console greys out what RBAC forbids\n- Form-based creation for benches and sites, alongside the console''s own\n  YAML editor\n- FPM package store aggregating every bench''s configured repositories, so\n  app installs resolve prebuilt packages and work air-gapped\n- Ships one image that also runs standalone on vanilla Kubernetes, choosing\n  its nginx config at startup from whether a serving certificate is mounted\n\nElastic License 2.0.","tree":{"sha":"5a5e62d4309ae3ba47052ac618ccbca91d911721","url":"https://api.github.com/repos/vyogotech/frappe-operator-console-plugin/git/trees/5a5e62d4309ae3ba47052ac618ccbca91d911721"},"url":"https://api.github.com/repos/vyogotech/frappe-operator-console-plugin/git/commits/b5851303ae486a774e5818165bf67dac8c50a512","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/333592221?v=4","events_url":"https://api.github.com/users/vyogo-dev/events{/privacy}","followers_url":"https://api.github.com/users/vyogo-dev/followers","following_url":"https://api.github.com/users/vyogo-dev/following{/other_user}","gists_url":"https://api.github.com/users/vyogo-dev/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/vyogo-dev","id":333592221,"login":"vyogo-dev","node_id":"U_kgDOE-I2nQ","organizations_url":"https://api.github.com/users/vyogo-dev/orgs","received_events_url":"https://api.github.com/users/vyogo-dev/received_events","repos_url":"https://api.github.com/users/vyogo-dev/repos","site_admin":false,"starred_url":"https://api.github.com/users/vyogo-dev/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/vyogo-dev/subscriptions","type":"User","url":"https://api.github.com/users/vyogo-dev","user_view_type":"public"},"html_url":"https://github.com/vyogotech/frappe-operator-console-plugin/commit/b5851303ae486a774e5818165bf67dac8c50a512","node_id":"C_kwDOUUeNZNoAKGI1ODUxMzAzYWU0ODZhNzc0ZTU4MTgxNjViZjY3ZGFjOGM1MGE1MTI","parents":[],"sha":"b5851303ae486a774e5818165bf67dac8c50a512","url":"https://api.github.com/repos/vyogotech/frappe-operator-console-plugin/commits/b5851303ae486a774e5818165bf67dac8c50a512"}],"requestUrl":"https://api.github.com/repos/vyogotech/frappe-operator-console-plugin/commits?per_page=100&page=1&sha=b5851303ae486a774e5818165bf67dac8c50a512&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A20%3A01.664Z"}');
